'use strict';
let entryMoodsOpen=false,entryAssociationOpen=new Set();
let entryMoods=[],entryAssociations=[],entryPeopleRefs=[],entryRestoredFrom=null,entryPeopleQuery='',mindPersonFilter='',mindMoodFilter='';
let solarPerson='',solarRole='',solarMood='',solarDay='',solarAt='',solarLimit=20,solarHistoryOpen=false,peopleQuery='',peopleShowArchived=false,quickPersonOpen=false;
const emptyPerson=()=>({name:'',role:'other',roleLabel:'',type:'person',description:'',color:AntarSolar.palette[0],archived:false});
let quickPersonDraft=emptyPerson(),profileDraft=emptyPerson(),profileEditing=null,personSaving=false;
const solarMoods=ids=>(ids||[]).map(id=>moodData.find(m=>m.id===id)).filter(Boolean);
function moodPills(ids,cls=''){return solarMoods(ids).map(m=>`<span class="solar-feeling ${cls}">${esc(m.name)}</span>`).join('')}
function personRef(person){return{id:person.id,name:person.name,role:person.role,roleLabel:person.roleLabel||'',type:person.type,color:AntarSolar.color(person.color)}}
function associationPerson(id,refs=entryPeopleRefs){return personalItems.find(p=>p.kind==='person'&&p.id===id)||refs.find(p=>p.id===id)||{id,name:'Removed profile',role:'other',type:'person',color:AntarSolar.palette[0]}}
function resetEntryAssociations(){entryMoodsOpen=false;entryAssociationOpen.clear();entryMoods=[];entryAssociations=[];entryPeopleRefs=[];entryRestoredFrom=null;entryPeopleQuery=''}
function loadEntryAssociations(item){const v=AntarSolar.thoughtAt(item);entryMoods=[...(v?.moodIds||[])];entryAssociations=(v?.associations||[]).map(a=>({...a,moodIds:[...a.moodIds]}));entryPeopleRefs=(v?.peopleSnapshots||[]).map(p=>({...p}));entryRestoredFrom=null}
function formPerson(context='manager'){const d=context==='writer'?quickPersonDraft:profileDraft;return `<div class="person-form"><label class="field" for="${context}-person-name">Nickname or character name</label><input id="${context}-person-name" data-person-field="name" data-person-context="${context}" maxlength="80" value="${esc(d.name)}" placeholder="A nickname is enough"><div class="filter-pair"><div><label class="field" for="${context}-person-type">This is</label><select id="${context}-person-type" data-person-field="type" data-person-context="${context}" class="section-select"><option value="person" ${d.type==='person'?'selected':''}>A person in my life</option><option value="character" ${d.type==='character'?'selected':''}>A character or symbol</option></select></div><div><label class="field" for="${context}-person-role">Role I choose</label><select id="${context}-person-role" data-person-field="role" data-person-context="${context}" class="section-select">${AntarSolar.roles.map(([id,label])=>`<option value="${id}" ${d.role===id?'selected':''}>${label}</option>`).join('')}</select></div></div><label class="field" for="${context}-person-label">My own role label <span class="small">(optional)</span></label><input id="${context}-person-label" data-person-field="roleLabel" data-person-context="${context}" maxlength="60" value="${esc(d.roleLabel)}" placeholder="For example: mother, old friend, or mentor"><label class="field" for="${context}-person-description">My perspective, in a few words <span class="small">(optional)</span></label><textarea id="${context}-person-description" data-person-field="description" data-person-context="${context}" maxlength="600" placeholder="What feels important to remember?">${esc(d.description)}</textarea><p class="field">A planet colour</p><div class="planet-colours">${AntarSolar.palette.map((color,i)=>`<button class="planet-swatch ${d.color===color?'chosen':''}" style="--planet:${color}" data-person-colour="${color}" data-person-context="${context}" aria-label="Planet colour ${i+1}" aria-pressed="${d.color===color}"><span></span></button>`).join('')}</div><button class="secondary" data-save-person="${context}" ${personSaving||!personalReady?'disabled':''}>${personSaving?'Saving…':context==='manager'&&profileEditing?'Save profile changes':context==='writer'?'Create & select for this thought':'Create this profile'}</button><p class="small">Only your record, on this device. This does not contact anyone, read their feelings, or assess their personality.</p></div>`}
function entryAssociationFields(){const all=personalItems.filter(p=>p.kind==='person'&&(!p.archived||entryAssociations.some(a=>a.personId===p.id))),q=entryPeopleQuery.toLowerCase(),shown=all.filter(p=>[p.name,AntarSolar.roleName(p)].join(' ').toLowerCase().includes(q)).slice(0,12);return `<section class="entry-associations"><div class="section-head"><h2>People &amp; feelings.</h2><a class="text-btn" href="#people">My people</a></div><p class="small">Optional, chosen by you. These tags stay with this thought; no mood check-in is created.</p><details data-entry-feelings ${entryMoodsOpen||entryMoods.length?'open':''}><summary>Feelings on this entry${entryMoods.length?' · '+entryMoods.length+' chosen':''}</summary><div class="chips solar-mood-picker">${moodData.map(m=>`<button class="chip ${entryMoods.includes(m.id)?'selected':''}" data-entry-mood="${m.id}" aria-pressed="${entryMoods.includes(m.id)}">${esc(m.name)}</button>`).join('')}</div>${selected.length?'<button class="text-btn" data-solar="use-current-moods">Use the feelings I already selected</button>':''}<p class="small">Nothing is guessed from your words. Leave feelings unnamed if you prefer.</p></details><label class="field" for="entry-person-search">Who is part of this thought?</label><input id="entry-person-search" type="search" value="${esc(entryPeopleQuery)}" placeholder="Find a person, character, or role"><div id="entry-people-options" class="people-picks">${peoplePickButtons(shown)}</div>${all.length>12?'<p class="small">Showing up to 12 matches. Search to find someone else.</p>':''}${entryAssociations.length?`<div class="chosen-people">${entryAssociations.map(a=>{const p=associationPerson(a.personId);return `<article class="person-association"><div class="association-name"><span class="tiny-planet" style="--planet:${AntarSolar.color(p.color)}">${esc(p.name.slice(0,1))}</span><strong>${esc(p.name)}</strong><span class="small">${esc(AntarSolar.roleName(p))}${p.archived?' · archived':''}</span><button class="text-btn" data-unpick-person="${esc(p.id)}" aria-label="Detach ${esc(p.name)} from this thought">×</button></div><details data-association-open="${esc(a.personId)}" ${entryAssociationOpen.has(a.personId)||a.moodIds.length||a.note?'open':''}><summary>A feeling or note specifically with ${esc(p.name)}? Optional.</summary><p class="small">Entry feelings are not automatically attributed to this person. Choose an association only if it fits your experience.</p><div class="chips solar-mood-picker">${moodData.map(m=>`<button class="chip ${a.moodIds.includes(m.id)?'selected':''}" data-link-mood="${m.id}" data-link-person="${esc(p.id)}" aria-pressed="${a.moodIds.includes(m.id)}">${esc(m.name)}</button>`).join('')}</div><label class="field" for="link-note-${esc(p.id)}">My experience with ${esc(p.name)}</label><input id="link-note-${esc(p.id)}" data-person-link-note="${esc(p.id)}" maxlength="300" value="${esc(a.note)}" placeholder="A moment, a change, or something still unclear"></details></article>`}).join('')}</div>`:''}<details data-quick-person ${quickPersonOpen?'open':''}><summary>+ Create a person or character</summary>${formPerson('writer')}</details></section>`}
function peoplePickButtons(people){return people.length?people.map(p=>`<button class="person-pick ${entryAssociations.some(a=>a.personId===p.id)?'selected':''}" data-pick-person="${esc(p.id)}" aria-pressed="${entryAssociations.some(a=>a.personId===p.id)}"><span class="tiny-planet" style="--planet:${AntarSolar.color(p.color)}">${esc(p.name.slice(0,1))}</span><span>${esc(p.name)}<small>${esc(AntarSolar.roleName(p))}${p.type==='character'?' · character':''}</small></span></button>`).join(''):'<p class="small">No profile matches. Create a nickname or character below.</p>'}
function thoughtAssociationBadges(item){const v=AntarSolar.thoughtAt(item);return `<div class="thought-tags">${moodPills(v?.moodIds)}${(v?.associations||[]).map(a=>{const p=associationPerson(a.personId,v.peopleSnapshots);return `<a href="#person/${encodeURIComponent(p.id)}" class="person-tag"><i style="background:${AntarSolar.color(p.color)}"></i>${esc(p.name)}</a>`}).join('')}${Array.isArray(item.versions)?`<span class="small">${item.versions.length} saved ${item.versions.length===1?'version':'versions'}</span>`:''}</div>`}
function entryFilters(){return `<div class="filter-pair"><div><label class="field" for="mind-person-filter">Person / character</label><select id="mind-person-filter" class="section-select"><option value="">Anyone or unnamed</option>${personalItems.filter(p=>p.kind==='person').map(p=>`<option value="${esc(p.id)}" ${mindPersonFilter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div><label class="field" for="mind-mood-filter">Feeling attached</label><select id="mind-mood-filter" class="section-select"><option value="">Any or unnamed</option>${moodData.map(m=>`<option value="${m.id}" ${mindMoodFilter===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div></div>`}
function filteredMindThoughts(){return AntarSolar.view(personalItems,{person:mindPersonFilter,mood:mindMoodFilter}).thoughts}
function solarNav(){return `<div class="solar-links"><a href="#people">People &amp; characters</a><a href="#thought-links">Thought-to-thought links</a></div>`}
function solarMap(){const snapshot=solarAt||solarDay;let data=AntarSolar.view(personalItems,{day:snapshot,person:solarPerson,mood:solarMood,role:solarRole});if(solarPerson&&!data.allPeople.some(p=>p.id===solarPerson)){solarPerson='';data=AntarSolar.view(personalItems,{day:snapshot,mood:solarMood,role:solarRole})}const focus=data.allPeople.find(p=>p.id===solarPerson),people=data.people.filter(p=>!p.archived||data.personCounts[p.id]>0),thoughts=data.thoughts;const nodes=focus?thoughts.slice(0,8).map(t=>({id:t.id,title:t.title||t.text.slice(0,36),sub:solarMoods(t.moodIds).map(m=>m.name).join(' + ')||'Thought',color:'#c6d1d0',thought:true,version:t.version})):people.slice(0,8).map(p=>({id:p.id,title:p.name,sub:AntarSolar.roleName(p),color:AntarSolar.color(p.color),count:data.personCounts[p.id]}));const events=AntarSolar.timeline(personalItems,{day:snapshot,person:solarPerson,mood:solarMood}).filter(v=>!solarRole||v.associations.some(a=>data.allPeople.some(p=>p.id===a.personId&&p.role===solarRole)));const days=AntarSolar.historyDays(personalItems);const timelineIndex=solarDay?Math.max(0,days.indexOf(solarDay)):days.length;return `${livingTabs('map')}<p class="greeting">Your thought solar system</p><h1>My universe.</h1><p class="sub">People and words, connected by you.</p><div class="solar-controls"><label class="field" for="solar-person">Look from</label><select id="solar-person" class="section-select"><option value="">Me · my universe</option>${data.allPeople.map(p=>`<option value="${esc(p.id)}" ${solarPerson===p.id?'selected':''}>${esc(p.name)} · ${esc(AntarSolar.roleName(p))}</option>`).join('')}</select></div>${snapshot?`<p class="small">Saved view · ${solarAt?savedTime(solarAt):esc(solarDay)+' · end of day'}</p>`:''}<div class="solar-scene" aria-label="${focus?'Thoughts linked to '+esc(focus.name):'Your people and selected thought connections'}"><svg viewBox="0 0 400 400" preserveAspectRatio="none" aria-hidden="true"><circle cx="200" cy="200" r="144"/><circle cx="200" cy="200" r="100" stroke-dasharray="3 8"/>${nodes.map((n,i)=>{const angle=i/Math.max(nodes.length,1)*Math.PI*2-Math.PI/2,x=200+144*Math.cos(angle),y=200+140*Math.sin(angle);return n.thought||n.count?`<path d="M200 200Q${x} 200 ${x} ${y}"/>`:''}).join('')}<circle class="solar-star" cx="60" cy="90" r="2"/><circle class="solar-star" cx="322" cy="280" r="2"/><circle class="solar-star" cx="270" cy="54" r="1.5"/></svg><button class="solar-sun" data-solar="all-people" aria-label="${focus?'Return to my universe':'Me, at the centre of my own records'}"><strong>${focus?esc(focus.name.slice(0,18)):'Me'}</strong><span>${focus?'Back to me':'My words'}</span></button>${nodes.map((n,i)=>{const angle=i/Math.max(nodes.length,1)*Math.PI*2-Math.PI/2,x=50+36*Math.cos(angle),y=50+35*Math.sin(angle);return `<button class="solar-planet ${n.thought?'thought-star':''}" style="left:${x}%;top:${y}%;--planet:${n.color}" ${n.thought?`data-solar-thought="${esc(n.id)}" data-solar-version="${n.version}"`:`data-solar-person="${esc(n.id)}"`} aria-label="${n.thought?'Open thought: ':''}${esc(n.title)}${n.count!==undefined?', '+n.count+' linked thoughts':''}"><span>${n.thought?'✧':esc(n.title.slice(0,1))}</span><strong>${esc(n.title.slice(0,16))}${n.title.length>16?'…':''}</strong></button>`}).join('')}${!nodes.length?'<p class="solar-empty">A little space for your first connection.</p>':''}</div><p class="small solar-caption">From Me, lines mark people linked in your entries. Select a person to see their linked thoughts. Orbits and colours are layout choices, not closeness, influence, or relationship scores. Up to eight nodes appear here; all matching entries are below.</p>${solarNav()}<details><summary>Filter roles or feelings</summary><div class="filter-pair"><div><label class="field" for="solar-role">Role</label><select id="solar-role" class="section-select"><option value="">All roles</option>${AntarSolar.roles.map(([id,label])=>`<option value="${id}" ${solarRole===id?'selected':''}>${label}</option>`).join('')}</select></div><div><label class="field" for="solar-mood">Feeling in an entry</label><select id="solar-mood" class="section-select"><option value="">Any / unnamed</option>${moodData.map(m=>`<option value="${m.id}" ${solarMood===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div></div></details><div class="solar-numbers"><span><strong>${thoughts.length}</strong> thoughts in this view</span><span><strong>${events.length}</strong> saved versions</span></div><details ${solarHistoryOpen?'open':''}><summary>A day in your saved history</summary><p class="small">See the latest version saved by the end of a day. This is saved history, not a reconstruction of unsaved thoughts.</p><label class="field" for="solar-day">As saved by</label><input id="solar-day" type="date" value="${esc(solarDay)}" max="${AntarSkills.dayKey(new Date())}">${days.length?`<label class="field" for="solar-time">Move through saved days</label><input id="solar-time" type="range" min="0" max="${days.length}" value="${timelineIndex}"><p class="small">${solarDay||'Latest saved state'}</p>`:''}<label class="field" for="solar-exact">Or choose an exact saved update</label><select id="solar-exact" class="section-select"><option value="">Use the day / latest state</option>${AntarSolar.historyTimes(personalItems).slice().reverse().map(at=>`<option value="${at}" ${solarAt===at?'selected':''}>${savedTime(at)}</option>`).join('')}</select>${solarAt?`<p class="small">Showing the state saved by ${savedTime(solarAt)}.</p>`:''}<button class="text-btn" data-solar="latest">Return to latest</button></details>${focus?`<div class="section-head"><h2>With ${esc(focus.name)}</h2><a class="text-btn" href="#person/${encodeURIComponent(focus.id)}">Profile &amp; role history</a></div><p class="small">${esc(AntarSolar.roleName(focus))}${focus.type==='character'?' · character / symbol':''}. Your explicitly chosen associations, not what caused a feeling.</p>${personMoodSummary(thoughts,focus.id)}<button class="secondary" data-write-person="${esc(focus.id)}">Write a thought with ${esc(focus.name)}</button>`:`<div class="solar-person-list">${people.map(p=>`<button data-solar-person="${esc(p.id)}"><span class="tiny-planet" style="--planet:${AntarSolar.color(p.color)}">${esc(p.name.slice(0,1))}</span><span><strong>${esc(p.name)}</strong><small>${esc(AntarSolar.roleName(p))}${p.type==='character'?' · character':''}</small></span><span>${data.personCounts[p.id]||0}</span></button>`).join('')}</div>`}<div class="section-head"><h2>Your flow of words</h2><a class="text-btn" href="#mind">Write</a></div><p class="small">A timeline of saved versions. Connections are yours; chronological order does not establish cause.</p>${events.length?`<div class="thought-flow">${events.slice(0,solarLimit).map(v=>flowCard(v)).join('')}</div>${events.length>solarLimit?'<button class="secondary" data-solar="more-history">Show 20 more versions</button>':''}`:'<div class="empty-space"><p>No saved thought versions match this view. Unrecorded moments are unknown.</p><a class="install-link" href="#mind">Write a thought</a><a class="install-link" href="#people">Create a person or character</a></div>'}${personalBackupControls()}`}
function flowCard(v){return `<article class="flow-card"><p class="small">${savedTime(v.savedAt)} · version ${v.version}${v.legacy?' · earliest available copy':''}</p><a href="#thought-version/${encodeURIComponent(v.thoughtId)}/${v.version}">${esc(v.title||v.text.slice(0,70)||'A thought')}</a><p>${esc(v.text.slice(0,180))}${v.text.length>180?'…':''}</p><div class="thought-tags">${moodPills(v.moodIds)}${(v.peopleSnapshots||[]).map(p=>`<span class="person-tag">${esc(p.name)} · ${esc(AntarSolar.roleName(p))}</span>`).join('')}</div></article>`}
function savedTime(value){return value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit'}):'Earlier saved text · date unavailable'}
function personMoodSummary(thoughts,id){const counts=AntarSolar.personMoodCounts(thoughts,id);return counts.length?`<div class="person-mood-counts">${counts.map(x=>`<span>${esc(moodData.find(m=>m.id===x.id)?.name||x.id)} <strong>${x.count}</strong></span>`).join('')}</div><p class="small">Counts use only feelings you explicitly associated with this person on these thought entries. General entry feelings aren’t assigned to them.</p>`:'<p class="small">No person-specific feelings chosen here. They stay unknown even if an entry has other feeling tags.</p>'}
function peoplePage(){const people=personalItems.filter(p=>p.kind==='person'&&(peopleShowArchived||!p.archived)).filter(p=>[p.name,AntarSolar.roleName(p),p.description].join(' ').toLowerCase().includes(peopleQuery.toLowerCase()));return `<a class="install-link" href="#mind-map">‹ My solar system</a><p class="greeting">People &amp; characters</p><h1>A name.<br>A place in your story.</h1><p class="sub">Real people or characters you create. Nicknames are enough. Roles describe your chosen context, not a psychological label.</p><details ${profileEditing?'open':''}><summary>${profileEditing?'Edit '+esc(profileEditing.name):'+ Create a person or character'}</summary>${formPerson('manager')}${profileEditing?'<button class="text-btn" data-solar="new-person">Close edit / create someone else</button>':''}</details><label class="field" for="people-search">Find a profile</label><input id="people-search" type="search" value="${esc(peopleQuery)}" placeholder="A nickname, role, or your words"><label class="revisit-switch"><input id="people-archived" type="checkbox" ${peopleShowArchived?'checked':''}>Include archived profiles</label><div class="people-directory">${people.map(p=>`<a href="#person/${encodeURIComponent(p.id)}"><span class="directory-planet" style="--planet:${AntarSolar.color(p.color)}">${esc(p.name.slice(0,1))}</span><span><h2>${esc(p.name)}</h2><p>${esc(AntarSolar.roleName(p))}${p.type==='character'?' · character / symbol':''}${p.archived?' · archived':''}</p></span><span>›</span></a>`).join('')||'<p class="empty">No profiles in this view. There’s no need to map everyone in your life.</p>'}</div>${personalBackupControls()}`}
function personPage(id){const p=personalItems.find(x=>x.kind==='person'&&x.id===id);if(!p)return `<a class="install-link" href="#people">‹ People &amp; characters</a><h1>${personalReady?'This profile isn’t here.':'Opening this profile…'}</h1><p class="sub">Saved thought versions keep the names and roles attached when you saved them.</p>${personalBackupControls()}`;const data=AntarSolar.view(personalItems,{person:id}),history=Array.isArray(p.versions)&&p.versions.length?p.versions:[AntarSolar.personSnapshot(p)];return `<a class="install-link" href="#people">‹ People &amp; characters</a><div class="person-profile"><span class="profile-planet" style="--planet:${AntarSolar.color(p.color)}">${esc(p.name.slice(0,1))}</span><p class="greeting">${p.type==='character'?'A character / symbol you created':'A person in your own record'}</p><h1>${esc(p.name)}</h1><p>${esc(AntarSolar.roleName(p))}${p.archived?' · archived from the writer':''}</p></div>${p.description?`<section class="profile-perspective"><h2>In your words</h2><p>${esc(p.description)}</p></section>`:''}<div class="chips"><button class="secondary" data-write-person="${esc(id)}">Write a thought with ${esc(p.name)}</button><button class="text-btn" data-person-edit="${esc(id)}">Update profile / role</button><button class="text-btn" data-person-archive="${esc(id)}">${p.archived?'Show in my writer again':'Archive from the writer'}</button><button class="text-btn" data-solar-person="${esc(id)}">Explore this orbit</button></div><h2>Feelings you associated here</h2>${personMoodSummary(data.thoughts,id)}<div class="section-head"><h2>Thoughts with ${esc(p.name)}</h2></div>${data.thoughts.length?data.thoughts.sort((a,b)=>Date.parse(b.savedAt)-Date.parse(a.savedAt)).map(t=>`<article class="person-thought"><a href="#thought/${encodeURIComponent(t.id)}">${esc(t.title||t.text.slice(0,70))}</a><p>${esc(t.text.slice(0,180))}</p>${moodPills(t.moodIds)}<p class="small">Entry feelings above are not attributed to ${esc(p.name)}. Your person-specific association is below.</p>${t.associations.filter(a=>a.personId===id).map(a=>`${moodPills(a.moodIds)}${a.note?`<p>${esc(a.note)}</p>`:''}`).join('')}<p class="small">${savedTime(t.savedAt)}</p></article>`).join(''):'<p class="empty">No thoughts linked yet. A profile alone does not imply a feeling or a relationship pattern.</p>'}<details><summary>Saved profile &amp; role history · ${history.length} versions</summary>${history.slice().reverse().map(v=>`<article class="profile-version"><p class="small">${savedTime(v.savedAt)}</p><strong>${esc(v.name)} · ${esc(AntarSolar.roleName(v))}</strong><p>${esc(v.description||'No perspective note added.')}</p><p class="small">${v.type==='character'?'Character / symbol':'Person'}${v.archived?' · archived':''}</p></article>`).join('')}</details><p class="note">This is a history of your own words and choices. It does not infer this person’s motives, feelings, or mental health.</p><details><summary>Remove this profile</summary><p class="small">Removing a profile does not erase names or descriptions you saved inside thoughts and their versions. Those thoughts have their own removal controls. Undo is available until this page reloads.</p><button class="text-btn" data-remove-person="${esc(id)}">Remove profile</button></details>${personalBackupControls()}`}
function thoughtHistory(item){const versions=AntarSolar.thoughtVersions(item);return `<details class="thought-history"><summary>Saved thought history · ${versions.length} ${versions.length===1?'version':'versions'}</summary><p class="small">History contains saved text and tags, never unsaved typing. For older entries, the earliest available copy may be the latest one saved before version history existed.</p>${versions.slice().reverse().map((v,index)=>`<article class="thought-version"><p class="small">${savedTime(v.savedAt)} · version ${v.version}${v.legacy?' · earliest available copy':''}</p><h3>${esc(v.title||'A thought, as it came')}</h3><p class="thought-full">${esc(v.text)}</p>${moodPills(v.moodIds)}${v.associations.map(a=>{const p=v.peopleSnapshots.find(x=>x.id===a.personId);return `<div class="version-association"><strong>${esc(p?.name||'Profile not available')} · ${esc(AntarSolar.roleName(p))}</strong><p class="small">Role captured with this save.</p>${moodPills(a.moodIds)}${a.note?`<p>${esc(a.note)}</p>`:''}</div>`}).join('')}<button class="text-btn" data-restore-thought="${esc(item.id)}" data-restore-version="${versions.length-1-index}">Use this version as an editable draft</button></article>`).join('')}</details>`}
function thoughtPeopleDetails(item){const v=AntarSolar.thoughtAt(item);return `<section class="thought-people"><h2>People &amp; feelings in this save</h2><div class="thought-tags">${moodPills(v.moodIds)||'<span class="small">Entry feeling left unnamed.</span>'}</div>${v.associations.map(a=>{const p=v.peopleSnapshots.find(x=>x.id===a.personId)||associationPerson(a.personId,[]),current=personalItems.find(x=>x.id===a.personId&&x.kind==='person');return `<article><${current?'a':'strong'} ${current?`href="#person/${encodeURIComponent(p.id)}"`:''}>${esc(p.name)}</${current?'a':'strong'}><p class="small">At this save: ${esc(AntarSolar.roleName(p))}${p.type==='character'?' · character / symbol':''}${!current?' · profile removed':''}</p>${moodPills(a.moodIds)||'<p class="small">No person-specific feeling selected.</p>'}${a.note?`<p>${esc(a.note)}</p>`:''}</article>`}).join('')||'<p class="small">No people attached. Nothing is assumed.</p>'}</section>${thoughtHistory(item)}`}
async function savePersonForm(context){if(personSaving||!personalReady)return;const draft=context==='writer'?quickPersonDraft:profileDraft,base=context==='manager'?profileEditing:null;if(!draft.name.trim())return toast('A nickname or character name first.');personSaving=true;try{const item=AntarSolar.savePerson(base,draft,new Date().toISOString(),personalId());await writePersonal(item,base?.updatedAt??null);if(context==='writer'){quickPersonDraft=emptyPerson();quickPersonOpen=false;if(!entryAssociations.some(a=>a.personId===item.id))entryAssociations.push({personId:item.id,moodIds:[],note:''});entryPeopleRefs=[...entryPeopleRefs.filter(x=>x.id!==item.id),personRef(item)]}else{profileDraft=emptyPerson();profileEditing=null}await refreshPersonal(true);if(context==='manager')go('person/'+encodeURIComponent(item.id));else render(true);toast('Profile saved. A thought is saved only when you choose Save.')}catch(error){toast(error.message||'Could not save. Your profile draft is still here.')}finally{personSaving=false;if(['mind','people'].includes(route))render(true)}}
function addPersonToDraft(person){if(!entryAssociations.some(a=>a.personId===person.id))entryAssociations.push({personId:person.id,moodIds:[],note:''});entryPeopleRefs=[...entryPeopleRefs.filter(x=>x.id!==person.id),personRef(person)]}
function toggleMood(list,id){if(!moodData.some(m=>m.id===id))return list;if(list.includes(id))return list.filter(x=>x!==id);if(list.length>=3){toast('Choose up to three feelings, or leave them unnamed.');return list}return [...list,id]}
function restoreThoughtDraft(item,index){const v=AntarSolar.thoughtVersions(item)[index];if(!v)return;if(mindText.trim()&&!confirm('Replace the open thought draft with this saved version? Unsaved words will be lost.'))return;mindEditing={...item};mindText=v.text;mindTitle=v.title;mindBucket=v.bucket;entryMoods=[...v.moodIds];entryAssociations=v.associations.map(a=>({...a,moodIds:[...a.moodIds]}));entryPeopleRefs=v.peopleSnapshots.map(p=>({...p}));entryRestoredFrom=v.version;go('mind')}
function clearSolarDrafts(){resetEntryAssociations();quickPersonDraft=emptyPerson();profileDraft=emptyPerson();profileEditing=null;quickPersonOpen=false;solarPerson='';solarRole='';solarMood='';solarDay='';solarAt='';mindPersonFilter='';mindMoodFilter='';peopleQuery=''}
document.addEventListener('input',event=>{const e=event.target;if(e.dataset.personField&&e.tagName!=='SELECT'){const d=e.dataset.personContext==='writer'?quickPersonDraft:profileDraft;d[e.dataset.personField]=e.value}if(e.dataset.personLinkNote){const a=entryAssociations.find(x=>x.personId===e.dataset.personLinkNote);if(a)a.note=e.value}if(e.id==='entry-person-search'){entryPeopleQuery=e.value;const q=e.value.toLowerCase(),people=personalItems.filter(p=>p.kind==='person'&&(!p.archived||entryAssociations.some(a=>a.personId===p.id))&&[p.name,AntarSolar.roleName(p)].join(' ').toLowerCase().includes(q)).slice(0,12);$('#entry-people-options').innerHTML=peoplePickButtons(people)}if(e.id==='people-search'){peopleQuery=e.value;render(true);const input=$('#people-search');input.focus();input.setSelectionRange(input.value.length,input.value.length)}});
document.addEventListener('toggle',event=>{if(event.target.matches?.('[data-entry-feelings]'))entryMoodsOpen=event.target.open;if(event.target.dataset?.associationOpen){if(event.target.open)entryAssociationOpen.add(event.target.dataset.associationOpen);else entryAssociationOpen.delete(event.target.dataset.associationOpen)}if(event.target.matches?.('[data-quick-person]'))quickPersonOpen=event.target.open},true);
document.addEventListener('change',event=>{const e=event.target;if(e.dataset.personField){const d=e.dataset.personContext==='writer'?quickPersonDraft:profileDraft;d[e.dataset.personField]=e.value}if(e.id==='mind-person-filter'){mindPersonFilter=e.value;$('#mind-results').innerHTML=mindCards()}if(e.id==='mind-mood-filter'){mindMoodFilter=e.value;$('#mind-results').innerHTML=mindCards()}if(e.id==='solar-person'){solarPerson=e.value;solarLimit=20;render(true)}if(e.id==='solar-role'){solarRole=e.value;solarPerson='';solarLimit=20;render(true)}if(e.id==='solar-mood'){solarMood=e.value;solarLimit=20;render(true)}if(e.id==='solar-exact'){solarAt=e.value;solarHistoryOpen=true;solarLimit=20;render(true)}if(e.id==='solar-day'){if(e.value&&!AntarSkills.validDay(e.value)){toast('Choose a valid saved day.');return}solarDay=e.value;solarAt='';solarHistoryOpen=true;solarLimit=20;render(true)}if(e.id==='solar-time'){const days=AntarSolar.historyDays(personalItems);solarDay=days[Number(e.value)]||'';solarAt='';solarHistoryOpen=true;solarLimit=20;render(true)}if(e.id==='people-archived'){peopleShowArchived=e.checked;render(true)}});
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;try{if(el.dataset.entryMood){entryMoods=toggleMood(entryMoods,el.dataset.entryMood);render(true);return}if(el.dataset.pickPerson){const id=el.dataset.pickPerson;if(entryAssociations.some(a=>a.personId===id))entryAssociations=entryAssociations.filter(a=>a.personId!==id);else{const p=personalItems.find(x=>x.id===id&&x.kind==='person');if(p)addPersonToDraft(p)}render(true);return}if(el.dataset.unpickPerson){entryAssociations=entryAssociations.filter(a=>a.personId!==el.dataset.unpickPerson);render(true);return}if(el.dataset.linkMood){const a=entryAssociations.find(x=>x.personId===el.dataset.linkPerson);if(a)a.moodIds=toggleMood(a.moodIds,el.dataset.linkMood);render(true);return}if(el.dataset.personColour){const d=el.dataset.personContext==='writer'?quickPersonDraft:profileDraft;d.color=AntarSolar.color(el.dataset.personColour);render(true);return}if(el.dataset.savePerson){await savePersonForm(el.dataset.savePerson);return}if(el.dataset.solarPerson){solarPerson=el.dataset.solarPerson;solarRole='';solarLimit=20;if(route==='mind-map')render(true);else go('mind-map');return}if(el.dataset.solarThought){go((solarDay||solarAt)?'thought-version/'+encodeURIComponent(el.dataset.solarThought)+'/'+el.dataset.solarVersion:'thought/'+encodeURIComponent(el.dataset.solarThought));return}if(el.dataset.writePerson){const p=personalItems.find(x=>x.id===el.dataset.writePerson&&x.kind==='person');if(p){addPersonToDraft(p);go('mind')}return}if(el.dataset.personEdit){const p=personalItems.find(x=>x.id===el.dataset.personEdit&&x.kind==='person');if(p){if(profileEditing&&profileDraft.name.trim()&&!confirm('Replace the open profile edit? Unsaved profile changes will be lost.'))return;profileEditing={...p};profileDraft={...emptyPerson(),...p};go('people')}return}if(el.dataset.personArchive){const p=personalItems.find(x=>x.id===el.dataset.personArchive&&x.kind==='person');if(p){const item=AntarSolar.savePerson(p,{...p,archived:!p.archived},new Date().toISOString(),p.id);await writePersonal(item,p.updatedAt);await refreshPersonal(true);toast(item.archived?'Archived from the writer; history stays.':'Available in your writer again.')}return}if(el.dataset.removePerson){const p=personalItems.find(x=>x.id===el.dataset.removePerson&&x.kind==='person');if(p&&confirm('Remove this profile? Names and roles saved in thought versions stay there. Undo is available until reload.')){lastPersonalGroup=await removePersonalGroup(p);lastPersonalRemoval=p;await refreshPersonal(true);go('people');toast('Profile removed. Undo is available below.')}return}if(el.dataset.restoreThought){const item=personalItems.find(x=>x.id===el.dataset.restoreThought&&x.kind==='thought');if(item)restoreThoughtDraft(item,Number(el.dataset.restoreVersion));return}switch(el.dataset.solar){case'use-current-moods':entryMoods=[...selected].slice(0,3);render(true);break;case'all-people':solarPerson='';render(true);break;case'latest':solarDay='';solarAt='';solarHistoryOpen=false;render(true);break;case'more-history':solarLimit+=20;render(true);break;case'new-person':if(profileDraft.name.trim()&&!confirm('Close this profile draft without saving?'))return;profileDraft=emptyPerson();profileEditing=null;render(true);break;}}catch(error){toast(error.message||'Could not save that change. Your draft is still here.')}});

function thoughtVersionPage(id,number){const item=personalItems.find(t=>t.id===id&&t.kind==='thought'),versions=item?AntarSolar.thoughtVersions(item):[],v=versions.find(x=>x.version===number);if(!v)return `<a class="install-link" href="#mind-map">‹ My solar system</a><h1>${personalReady?'This saved version is not here.':'Opening saved history…'}</h1>`;return `<a class="install-link" href="#thought/${encodeURIComponent(id)}">‹ Latest entry &amp; full history</a><p class="greeting">Saved version ${v.version} · ${savedTime(v.savedAt)}</p><h1>${esc(v.title||'A thought, as it was')}</h1><p class="small">A historical saved copy. This may differ from the current entry.</p><p class="thought-full">${esc(v.text)}</p>${moodPills(v.moodIds)}${v.associations.map(a=>{const p=v.peopleSnapshots.find(x=>x.id===a.personId);return `<div class="version-association"><strong>${esc(p?.name||'Profile not available')} · ${esc(AntarSolar.roleName(p))}</strong><p class="small">Role captured with this save.</p>${moodPills(a.moodIds)}${a.note?`<p>${esc(a.note)}</p>`:''}</div>`}).join('')}<button class="secondary" data-restore-thought="${esc(id)}" data-restore-version="${versions.indexOf(v)}">Use this version as an editable draft</button><p class="note">Saving the draft creates a new version. Earlier saved versions are not overwritten.</p>`}
